from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    seeds=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,1)]
    out=[row[:] for row in g]
    seen=set()
    for sr,sc in seeds:
        if (sr,sc) in seen: continue
        color=g[sr][sc]
        comp=[(sr,sc)]; seen.add((sr,sc)); q=deque([(sr,sc)])
        while q:
            r,c=q.popleft()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]!=0:
                    if g[nr][nc]!=1 and g[nr][nc]!=color:
                        comp=None;break
                    seen.add((nr,nc)); comp.append((nr,nc)); q.append((nr,nc))
            if comp is None: break
        if comp:
            for r,c in comp: out[r][c]=color
    return out

